def subtract(a, b):
    # Filter out empty intervals and merge overlapping ones
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Sort by start, then by end
        sorted_intervals = sorted(intervals)
        merged = []

        for start, end in sorted_intervals:
            if start >= end:  # Skip empty intervals
                continue

            if merged and start <= merged[-1][1]:
                # Overlapping or touching, merge them
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])

        return merged

    # Merge both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current_start = a_start

        for b_start, b_end in b_merged:
            if b_end <= current_start:
                # b interval is completely before current interval
                continue

            if b_start >= a_end:
                # b interval is completely after current interval
                break

            # There's an overlap
            if b_start > current_start:
                # Add the part before b_start
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part of a after processing all b intervals
        if current_start < a_end:
            result.append([current_start, a_end])

    return result

